WITH by_dimension AS (SELECT d.segment, a.plan, COUNT(*) AS rows_total, MAX(a.monthly_fee) AS max_monthly_fee FROM subscriptions a INNER JOIN customers d ON a.customer_id = d.id GROUP BY d.segment, a.plan) SELECT segment, plan, rows_total, CASE WHEN segment RLIKE '^(SMB|Consumer)$' THEN 'EXTENDED' WHEN segment RLIKE '^(Corporate)$' THEN 'CORE' ELSE 'GROUP_B' END AS segment_zone FROM by_dimension ORDER BY plan, segment_zone;
